# name: late_vs_early_discrimination
# description: Correlation between each answer and its (set,target) cell's mean yes rate in the second half of each session (trial_index>=225) minus the same in the first half; positive vs the null means people get sharper/more consistent with the consensus as the session goes on (negative: noisier), which a static model cannot produce.
def test_statistic(df):
    key = df["number_set"].astype(str) + "|" + df["target"].astype(str)
    y = df["rating"].astype(float)
    cm = y.groupby(key).transform("mean").values
    yv = y.values
    late = df["trial_index"].astype(int).values >= 225
    def corr(m):
        a, b = yv[m], cm[m]
        if a.std() == 0 or b.std() == 0:
            return 0.0
        return float(np.corrcoef(a, b)[0, 1])
    return corr(late) - corr(~late)

# name: mersenne_fermat_target_contrast
# description: In sets whose examples are all of the form 2^k-1 (e.g. 31,3,1,15) or all 2^k+1 (e.g. 33,17,5,9), yes rate for unshown odd targets of the same form minus yes rate for other odd targets; observed above the null means people use "one off a power of 2" concepts the model lacks (model under-produces the contrast).
def test_statistic(df):
    sets = df["number_set"].astype(str)
    t = df["target"].astype(int).values
    y = df["rating"].astype(float).values
    minus = {2**k - 1 for k in range(1, 8) if 2**k - 1 <= 100}
    plus = {2**k + 1 for k in range(0, 7) if 2**k + 1 <= 100}
    uniq = sets.unique()
    fam = {}
    for s in uniq:
        ex = [int(v) for v in s.split(",")]
        if len(ex) < 2:
            continue
        if all(e in minus for e in ex):
            fam[s] = (minus, set(ex))
        elif all(e in plus for e in ex):
            fam[s] = (plus, set(ex))
    if not fam:
        return 0.0
    m = sets.isin(list(fam)).values
    inside = np.zeros(len(df), bool)
    shown = np.zeros(len(df), bool)
    sv = sets.values
    for s, (F, ex) in fam.items():
        r = sv == s
        inside |= r & np.isin(t, list(F))
        shown |= r & np.isin(t, list(ex))
    odd = (t % 2 == 1)
    a = m & inside & ~shown & odd
    b = m & ~inside & odd
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())

# name: odd_rule_conjunction_contrast
# description: In sets of >=2 all-odd examples that are all multiples of some m in {3,5,7,9} or all squares, yes rate for unshown odd members of that rule minus yes rate for even members of it; observed above the null means people infer the conjunction "odd AND rule" more sharply than the model's mixture of separate rules (model under-produces the contrast).
def test_statistic(df):
    sets = df["number_set"].astype(str)
    t = df["target"].astype(int).values
    y = df["rating"].astype(float).values
    sv = sets.values
    sq = {n * n for n in range(1, 11)}
    a_mask = np.zeros(len(df), bool)
    b_mask = np.zeros(len(df), bool)
    for s in sets.unique():
        ex = [int(v) for v in s.split(",")]
        if len(ex) < 2 or any(e % 2 == 0 for e in ex):
            continue
        r = sv == s
        member = np.zeros(len(df), bool)
        for m in (3, 5, 7, 9):
            if all(e % m == 0 for e in ex):
                member |= (t % m == 0)
        if all(e in sq for e in ex):
            member |= np.isin(t, list(sq))
        if not member.any():
            continue
        unshown = ~np.isin(t, ex)
        a_mask |= r & member & unshown & (t % 2 == 1)
        b_mask |= r & member & (t % 2 == 0)
    if a_mask.sum() == 0 or b_mask.sum() == 0:
        return 0.0
    return float(y[a_mask].mean() - y[b_mask].mean())
